export const fields=['date','campaign','channel','spend','revenue','impressions','clicks','conversions'];
export const channels=['Paid Search','Paid Social','Email'];
const monthlyDemo=Array.from({length:3},(_,m)=>channels.map((channel,c)=>({date:`2026-0${m+7}-01`,campaign:['Search · High intent','Social · Summer discovery','Email · Customer reactivation'][c],channel,spend:[3200,2600,450][c]+m*[180,130,30][c],revenue:[14200,8100,4900][c]+m*[1800,350,650][c],impressions:[125000,340000,22000][c]+m*7000,clicks:[6200,5100,2400][c]+m*300,conversions:[220,135,98][c]+m*[22,6,14][c]}))).flat();
// Add three earlier synthetic months; original July–September totals remain unchanged.
monthlyDemo.unshift(...Array.from({length:3},(_,m)=>channels.map((channel,c)=>({date:`2026-0${m+4}-01`,campaign:['Search · High intent','Social · Summer discovery','Email · Customer reactivation'][c],channel,spend:[2400,2100,300][c]+m*[220,140,40][c],revenue:[9500,5300,3000][c]+m*[1350,800,450][c],impressions:[100000,270000,16000][c]+m*5000,clicks:[4200,3700,1500][c]+m*310,conversions:[145,82,55][c]+m*[23,13,12][c]}))).flat());
// Distribute fictional monthly totals into deterministic daily observations.
export const demo=monthlyDemo.flatMap(row=>{
 const [year,month]=row.date.split('-').map(Number),days=new Date(Date.UTC(year,month,0)).getUTCDate();
 const weights=Array.from({length:days},(_,i)=>1+((i*7+month*3)%11)/12),total=weights.reduce((a,b)=>a+b,0);let cumulative=0;
 return weights.map((weight,i)=>{const before=cumulative;cumulative+=weight;return {...row,objective:row.channel==='Paid Search'?'Lead generation':row.channel==='Email'?'Retention':'Awareness',date:`${year}-${String(month).padStart(2,'0')}-${String(i+1).padStart(2,'0')}`,...Object.fromEntries(fields.slice(3).map(key=>[key,Math.floor(row[key]*cumulative/total+1e-8)-Math.floor(row[key]*before/total+1e-8)]))}});
});

export function aggregate(rows){return rows.reduce((s,r)=>{for(const k of fields.slice(3))s[k]+=r[k];return s},Object.fromEntries(fields.slice(3).map(k=>[k,0])))}
export const ratio=(a,b)=>b?a/b:null;
export function parseCSV(text){if(text.length>500000)throw Error('CSV must be under 500 KB.');let rows=[],row=[],cell='',quoted=false; text=text.replace(/^\uFEFF/,'');for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++}else if(quoted||cell==='')quoted=!quoted;else throw Error('Invalid CSV quoting.')}else if(c===','&&!quoted){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(x=>x.trim()))rows.push(row);row=[];cell=''}else cell+=c;}if(quoted)throw Error('Unclosed CSV quote.');row.push(cell);if(row.some(x=>x.trim()))rows.push(row);const header=rows.shift()?.map(x=>({day:'date',campaign_name:'campaign',cost:'spend',sales:'revenue',channel_name:'channel',conversion:'conversions'}[x.trim().toLowerCase().replaceAll(' ','_')]||x.trim().toLowerCase()));if(!header||fields.some(k=>!header.includes(k))||new Set(header).size!==header.length)throw Error('Required unique headers: '+fields.join(', '));if(!rows.length||rows.length>1000)throw Error('Upload 1–1,000 data rows.');return rows.map((r,i)=>{if(r.length!==header.length)throw Error(`Row ${i+2}: wrong column count.`);const o=Object.fromEntries(header.map((k,j)=>[k,r[j].trim()]));if(/^\d{1,2}\/\d{1,2}\/\d{4}$/.test(o.date)){const [m,d,y]=o.date.split('/');o.date=`${y}-${m.padStart(2,'0')}-${d.padStart(2,'0')}`}if(!/^\d{4}-\d{2}-\d{2}$/.test(o.date)||!Number.isFinite(Date.parse(o.date))||new Date(o.date).toISOString().slice(0,10)!==o.date)throw Error(`Row ${i+2}: use a valid YYYY-MM-DD date.`);if(!o.campaign||o.campaign.length>100||!channels.includes(o.channel))throw Error(`Row ${i+2}: campaign required; channel must be Paid Search, Paid Social, or Email.`);for(const k of fields.slice(3)){if(o[k]===''||!/^\d+(\.\d+)?$/.test(o[k]))throw Error(`Row ${i+2}: ${k} must be nonnegative.`);o[k]=Number(o[k]);if(!Number.isFinite(o[k])||o[k]>1e10||(['impressions','clicks','conversions'].includes(k)&&!Number.isInteger(o[k])))throw Error(`Row ${i+2}: invalid ${k}.`)}if(o.clicks>o.impressions||o.conversions>o.clicks)throw Error(`Row ${i+2}: conversions ≤ clicks ≤ impressions required.`);const result=Object.fromEntries(fields.map(k=>[k,o[k]]));if(o.objective){if(o.objective.length>100)throw Error('Objective too long.');result.objective=o.objective}if(o.engagements!==undefined&&o.engagements!==''){if(!/^\d+$/.test(o.engagements)||Number(o.engagements)>1e10)throw Error('Invalid engagements.');result.engagements=Number(o.engagements)}return result})}
export function csv(rows){const exportFields=[...fields,...(['objective','engagements'].filter(k=>rows.some(r=>r[k]!==undefined)))];const escape=v=>'"'+String(v).replace(/^\s*[=+@\-]/,"'$&").replaceAll('"','""')+'"';return [exportFields.join(','),...rows.map(r=>exportFields.map(k=>escape(r[k]??'')).join(','))].join('\r\n')}
